/**
 * Tester r1 (D193): differential fuzz of the browser's compute.yaml subset reader against the
 * CLI's loader (PyYAML safe_load + no aliases + no duplicate keys). The corpus
 * (yamlCorpus_v08_g4_tester_r1.json) is generated by tests/_support/v08_g4_yaml_corpus.py and
 * verified against PyYAML by tests/unit/test_v08_g4_tester_r1_yaml_corpus.py.
 *
 * Invariant: the parser either REFUSES (throws ManifestYamlError) or returns exactly what the CLI
 * loader returns. A different successful value is a mis-parse (critical). Accepting text the CLI
 * rejects is reported separately (the controller revalidates, but the browser would behave
 * differently from `compute run`).
 */
import { describe, expect, it } from "vitest";

import corpus from "./yamlCorpus_v08_g4_tester_r1.json";
import { ManifestYamlError, parseManifestYaml } from "./manifestYaml";

interface Case {
  text: string;
  expect: { ok?: unknown; error?: boolean; exotic?: boolean };
}

function run(text: string): { value?: unknown; refused?: true; crashed?: string } {
  try {
    return { value: parseManifestYaml(text) };
  } catch (error) {
    if (error instanceof ManifestYamlError) return { refused: true };
    return { crashed: String(error) };
  }
}

function same(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b) && typeof a === typeof b;
}

const all = corpus as Case[];
// Known defect classes are pinned by the explicit it.fails tests below; the corpus guards run on the rest.
const T1_UNICODE_WS = /[\u0085\u00a0\u2028\u2029\u3000]/; // T-1
const T2_QUESTION = /\?/; // T-2 (`?` complex-key indicator)
const T3_RANGE = /\\U00110000|\\ud8/; // T-3 + lone-surrogate escapes (CLI value itself is not encodable)
const cases = all.filter((c) => !T1_UNICODE_WS.test(c.text) && !T2_QUESTION.test(c.text) && !T3_RANGE.test(c.text));

describe("yaml differential vs PyYAML (tester r1)", () => {
  it("never mis-parses: any accepted document equals the CLI's value", () => {
    const bad: string[] = [];
    for (const c of cases) {
      const r = run(c.text);
      if (r.refused === true) continue;
      if (r.crashed !== undefined) continue; // counted by the crash test
      if ("ok" in c.expect) {
        if (!same(r.value, c.expect.ok)) bad.push(`${JSON.stringify(c.text)} -> ${JSON.stringify(r.value)} vs ${JSON.stringify(c.expect.ok)}`);
      }
    }
    expect(bad.slice(0, 25), `${bad.length} mis-parses`).toEqual([]);
  });

  it("never throws a non-ManifestYamlError", () => {
    const bad = cases.map((c) => [c.text, run(c.text)] as const).filter(([, r]) => r.crashed !== undefined);
    expect(bad.slice(0, 15).map(([t, r]) => `${JSON.stringify(t)} ${r.crashed ?? ""}`)).toEqual([]);
  });

  it("refuses values the CLI loads to something JSON cannot carry (dates, nan, inf, huge ints)", () => {
    const bad = cases
      .filter((c) => c.expect.exotic === true)
      .filter((c) => run(c.text).refused !== true)
      .map((c) => JSON.stringify(c.text));
    expect(bad.slice(0, 25), `${bad.length} cases`).toEqual([]);
  });

  // T-4: the reader is more lenient than PyYAML (stray ]/}, [,a], [a,,b], control chars, `k: - x`).
  it.fails("T-4 refuses what the CLI loader rejects (accepting = browser/CLI disagree)", () => {
    const bad = cases
      .filter((c) => c.expect.error === true)
      .filter((c) => run(c.text).refused !== true)
      .map((c) => JSON.stringify(c.text));
    expect(bad.slice(0, 100), `${bad.length} cases`).toEqual([]);
  });

  it.fails("T-1 YAML whitespace is only space/tab (NBSP, U+3000, U+2028 are content, not blanks)", () => {
    expect(run("a: \u00a0x\n").value).toEqual({ a: "\u00a0x" });
    expect(run("a: \u2028x\n").refused ?? run("a: \u2028x\n").value).toEqual({ a: "\u2028x" });
  });

  it.fails("T-2 the `?` complex-key indicator is refused everywhere (block list item, top level, flow)", () => {
    for (const t of ["- ? x\n", "? x\n", "k:\n  - ? x\n", "a: [?x]\n", "a: {?: 1}\n"]) {
      expect(run(t).refused, JSON.stringify(t)).toBe(true);
    }
  });

  it.fails("T-3 a bad escape (\\U00110000) is a ManifestYamlError, not a RangeError", () => {
    expect(run('a: "\\U00110000"\n').crashed).toBeUndefined();
  });

  it("accepts the common manifest shapes (not over-refusing)", () => {
    const wanted = [
      "name: demo\nrun: python x.py\n",
      "name: demo\nrun: [python, -c, 'print(1)']\ninputs:\n  - path: data\n    as_env: true\n",
      "env:\n  A: 'yes'\n  B: yes\n",
    ];
    for (const t of wanted) expect(run(t).refused).toBeUndefined();
  });
});
